import json, random, sys, traceback
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/work')
from utils import run_request
from ref import Ref


def gen_borders(rng, U, max_ranges=6):
    n = rng.randint(1, max_ranges)
    pts = sorted(rng.sample(range(1, U), min(n, U - 1))) if U > 1 else []
    return [0] + pts + [U]


def gen_run(rng, ops=40):
    M = rng.randint(1, 4)
    L = rng.randint(1, 3)
    U = rng.choice([1, 2, 5, 10, 40])
    fifo_bytes = rng.choice([1, 3, 8, 20, 100])
    pifo_bytes = rng.choice([1, 3, 8, 20, 100])
    refill_batch = rng.randint(1, 4)
    sample_period = rng.choice([1, 2, 3, 5, 100])
    borders = gen_borders(rng, U)
    kind = rng.choice(["fifo", "sp", "sff", "wfq"])
    flows = list(range(rng.randint(1, 5)))
    if kind == "sp":
        policy = {"kind": "sp",
                  "levels": [[f, rng.randint(0, U)] for f in flows]}
    elif kind == "wfq":
        policy = {"kind": "wfq",
                  "weights": [[f, rng.randint(1, 8)] for f in flows]}
    else:
        policy = {"kind": kind}
    events = []
    ids = 0
    saved = []
    for _ in range(ops):
        c = rng.random()
        if c < 0.45:
            ids += 1
            flow = rng.choice(flows)
            events.append(["enqueue", ids * 7, flow,
                           rng.randint(1, 12), rng.randint(0, U * 2)])
        elif c < 0.65:
            events.append(["dequeue", rng.randint(1, 4)])
        elif c < 0.72:
            events.append(["sample"])
        elif c < 0.78:
            events.append(["repartition", gen_borders(rng, U)])
        elif c < 0.86:
            pick = rng.randint(1, ids) * 7 if ids and rng.random() < 0.8 else 9999
            events.append(["cancel", pick])
        elif c < 0.92:
            pick = rng.randint(1, ids) * 7 if ids and rng.random() < 0.8 else 9999
            events.append(["inspect", pick])
        elif c < 0.95 and kind == "wfq":
            events.append(["weight", rng.choice(flows), rng.randint(1, 8)])
        elif c < 0.97:
            name = rng.randint(0, 3)
            events.append(["save", name])
            if name not in saved:
                saved.append(name)
        else:
            if saved:
                events.append(["restore", rng.choice(saved)])
            else:
                events.append(["sample"])
    return {"banks": M, "load_balancers": L, "fifo_bytes": fifo_bytes,
            "pifo_bytes": pifo_bytes, "refill_batch": refill_batch,
            "sample_period": sample_period, "borders": borders,
            "policy": policy, "events": events}


def one(seed):
    rng = random.Random(seed)
    cfg = gen_run(rng, ops=rng.randint(1, 60))
    req = {"runs": [cfg]}
    got = run_request(req)
    ref = Ref(cfg)
    log = ref.run(cfg["events"])
    exp = {"runs": [{"log": log, "state": ref.certificate()}]}
    if json.loads(json.dumps(got)) != exp:
        return cfg, got, exp
    return None


def main():
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 500
    base = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    fails = 0
    for seed in range(base, base + n):
        res = one(seed)
        if res:
            fails += 1
            cfg, got, exp = res
            print("FAIL seed", seed)
            if fails == 1:
                print(json.dumps(cfg))
                for a, b in zip(got["runs"][0]["log"], exp["runs"][0]["log"]):
                    if a != b:
                        print("got:", json.dumps(a))
                        print("exp:", json.dumps(b))
                        break
                if got["runs"][0]["state"] != exp["runs"][0]["state"]:
                    print("state got:", json.dumps(got["runs"][0]["state"]))
                    print("state exp:", json.dumps(exp["runs"][0]["state"]))
                # replay narrowed
            if fails >= 3:
                break
    print(f"done {n} seeds, {fails} failures")


if __name__ == "__main__":
    main()
